exec(compile('"""Run-scoped deterministic extraction v2. Never receives reference answers."""\nimport json\nimport re\nfrom extraction_v1 import repair as repair_v1, MC, CODE, ENABLED\n\n\ndef clean(text):\n    # Decode literal newlines only, preserving LaTeX escapes such as \\frac.\n    return str(text or \'\').replace(\'\\\\r\\\\n\', \'\\n\').replace(\'\\\\n\', \'\\n\').replace(\'**\', \'\').strip()\n\n\ndef option(text, letters=\'ABCD\'):\n    text = clean(text).strip(\'`\').strip()\n    m = re.fullmatch(r\'\\(?([\' + letters + r\'])\\)?[.!]?\', text, re.I)\n    if m:\n        return m[1].upper()\n    m = re.match(r\'^(?:\\(([\' + letters + r\'])\\)|([\' + letters + r\'])[.)]\\s+)(.+)$\', text, re.S | re.I)\n    if not m:\n        return \'\'\n    tail = m[3]\n    if re.search(r\'\\([A-Z]\\)|\\b(?:or|and)\\s+[A-Z]\\b|\\b[A-Z][.)]\\s|\\b(?:not correct|incorrect|wrong|not the answer)\\b\', tail):\n        return \'\'\n    return (m[1] or m[2]).upper()\n\n\ndef final_field(raw):\n    text = clean(raw)\n    hits = []\n    # A final named field may be inline; complete_prediction is not prediction.\n    for pattern in [r\'(?im)(?<![\\w])prediction\\s*:\\s*([^\\n]+)\',\n                    r\'(?im)\\b(?:(?:the|correct|final)\\s+){0,2}answer\\s*(?:is\\s*[:=]?|[:=])\\s*([^\\n]+)\']:\n        for m in re.finditer(pattern, text):\n            if not text[m.end():].strip():\n                hits.append((m.start(), m[1].strip().strip(\'`\'), \'final_field\'))\n    for m in re.finditer(r\'\\\\boxed\\s*\\{\', text):\n        depth = 1\n        for end in range(m.end(), len(text)):\n            depth += (text[end] == \'{\') - (text[end] == \'}\')\n            if depth == 0:\n                hits.append((m.start(), text[m.end():end].strip(), \'boxed\'))\n                break\n    return max(hits, default=(-1, \'\', \'\'), key=lambda x: x[0])[1:]\n\n\ndef repair(benchmark, raw, original, *, finish_reason=\'\', options=\'\'):\n    if benchmark not in MC | {\'agieval\', \'bbh\', \'popqa\'}:\n        return repair_v1(benchmark, raw, original, finish_reason=finish_reason, options=options)\n    raw = clean(raw)\n    original = str(original or \'\')\n    is_mc = benchmark in MC\n    letters = \'ABCD\'\n    if benchmark == \'agieval\':\n        try:\n            choices = json.loads(options) if isinstance(options, str) else options\n        except (ValueError, TypeError):\n            choices = []\n        is_mc = isinstance(choices, list) and bool(choices)\n        letters = \'ABCDEFGHIJKLMNOPQRSTUVWXYZ\'[:len(choices)] if is_mc else \'\'\n    if finish_reason == \'length\':\n        # Do not mine an unfinished chain of reasoning for new answers.\n        if is_mc:\n            selected = option(original, letters)\n            return selected, \'truncated_existing_explicit_only\'\n        return original, \'truncated_no_fallback\'\n    candidate, source = final_field(raw)\n    if is_mc:\n        if source:\n            return option(candidate, letters), \'final_choice\' if option(candidate, letters) else \'ambiguous_final_choice\'\n        # Only a response consisting solely of an option, not arbitrary prose.\n        bare = re.sub(r\'^complete_prediction:\\s*\', \'\', raw)\n        if \'\\n\' not in bare:\n            selected = option(bare, letters)\n            if selected:\n                return selected, \'bare_choice\'\n        # Existing short atomic results remain valid. Never scan prose for letters.\n        selected = option(original, letters)\n        return (selected, \'original_explicit_choice\') if selected else (\'\', \'unresolved_choice\')\n    if source:\n        if benchmark == \'popqa\':\n            candidate = candidate.strip(\' ."\\\'\')\n        return candidate, \'explicit_final_answer\'\n    return repair_v1(benchmark, raw, original, finish_reason=finish_reason, options=options)\n\n\ndef bbh_normalized(text):\n    value = clean(text).strip(\'`\').strip()\n    m = re.fullmatch(r\'\\(?([A-Z])\\)?[.!]?\', value, re.I)\n    if m:\n        return m[1].lower()\n    # Keep bracket sequences intact; parentheses matter outside single choices.\n    value = value.lower().replace(\'$\', \'\').replace(r\'\\,\', \'\').replace(r\'\\!\', \'\')\n    value = value.replace(r\'\\left\', \'\').replace(r\'\\right\', \'\')\n    value = re.sub(r\'\\\\text\\{([^{}]*)\\}\', r\'\\1\', value)\n    return re.sub(r\'\\s+\', \'\', value).strip(\' .,:;!"\\\'\')\n',__file__,"exec"),m.__dict__)
